CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL DEFAULT '', password VARCHAR(255) NOT NULL, role ENUM('customer','staff','admin') NOT NULL DEFAULT 'customer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vehicles (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(30) NOT NULL, model VARCHAR(100) NOT NULL, plate VARCHAR(15) NOT NULL DEFAULT '', FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS services (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(140) NOT NULL,description TEXT NOT NULL,duration INT NOT NULL DEFAULT 60,price_cents INT UNSIGNED NULL,mode ENUM('fixed','vehicle','quote') NOT NULL DEFAULT 'quote',vehicle_types JSON NOT NULL,image VARCHAR(255) NOT NULL DEFAULT '',featured BOOLEAN NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,FOREIGN KEY(category_id) REFERENCES categories(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_prices (service_id BIGINT UNSIGNED NOT NULL,vehicle_type VARCHAR(30) NOT NULL,price_cents INT UNSIGNED NOT NULL,PRIMARY KEY(service_id,vehicle_type),FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS promotions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,code VARCHAR(40) NULL UNIQUE,type ENUM('percent','fixed') NOT NULL,value INT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,service_ids JSON NOT NULL,min_cents INT UNSIGNED NOT NULL DEFAULT 0,max_uses INT UNSIGNED NULL,per_user_limit INT UNSIGNED NOT NULL DEFAULT 1,active BOOLEAN NOT NULL DEFAULT 1
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,vehicle_types JSON NOT NULL,active BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS schedule_days (weekday TINYINT UNSIGNED PRIMARY KEY,opens TIME NOT NULL,closes TIME NOT NULL,break_start TIME NULL,break_end TIME NULL,active BOOLEAN NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS blocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,resource_id BIGINT UNSIGNED NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,reason VARCHAR(200) NOT NULL,FOREIGN KEY(resource_id) REFERENCES resources(id),INDEX(starts_at,ends_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bookings (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reference CHAR(24) NOT NULL UNIQUE,user_id BIGINT UNSIGNED NOT NULL,vehicle_id BIGINT UNSIGNED NOT NULL,resource_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,expires_at DATETIME NULL,status ENUM('reserved','confirmed','in_progress','ready','completed','cancelled','expired','review') NOT NULL DEFAULT 'reserved',payment_status VARCHAR(30) NOT NULL DEFAULT 'pending',subtotal_cents INT UNSIGNED NOT NULL,discount_cents INT UNSIGNED NOT NULL DEFAULT 0,pickup_cents INT UNSIGNED NOT NULL DEFAULT 0,total_cents INT UNSIGNED NOT NULL,promotion_id BIGINT UNSIGNED NULL,pickup JSON NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),FOREIGN KEY(resource_id) REFERENCES resources(id),FOREIGN KEY(promotion_id) REFERENCES promotions(id),INDEX(resource_id,starts_at,ends_at),INDEX(user_id,status)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS booking_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,name VARCHAR(140) NOT NULL,price_cents INT UNSIGNED NOT NULL,duration INT NOT NULL,FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(service_id) REFERENCES services(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NOT NULL,provider_id VARCHAR(80) NULL UNIQUE,preference_id VARCHAR(120) NULL,checkout_url TEXT NULL,status VARCHAR(40) NOT NULL DEFAULT 'pending',amount_cents INT UNSIGNED NOT NULL,event_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id),INDEX(booking_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payment_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id VARCHAR(80) NOT NULL,event_key VARCHAR(190) NOT NULL UNIQUE,result VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY,value JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS secrets (name VARCHAR(80) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS content (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kind ENUM('faq','gallery','banner','policy') NOT NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,image VARCHAR(255) NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,details JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identity_hash CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(identity_hash,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used BOOLEAN NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,booking_id BIGINT UNSIGNED NULL,kind VARCHAR(30) NOT NULL,message TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'open',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(booking_id) REFERENCES bookings(id)) ENGINE=InnoDB;
